import React, { useState, useEffect, useRef, useCallback } from 'react';
import api from '../../api';

const DEFAULT_POPULAR = [
    'RELIANCE', 'TCS', 'HDFCBANK', 'INFY', 'ICICIBANK', 
    'SBIN', 'BHARTIARTL', 'ITC', 'WIPRO', 'HCLTECH',
    'TATAMOTORS', 'TATASTEEL', 'MARUTI', 'SUNPHARMA', 'BAJFINANCE'
];

const Explore = ({ onSelectStock }) => {
    const [marketTab, setMarketTab] = useState('indian'); // 'indian', 'global', 'fno', 'gainers'
    const [indianIndices, setIndianIndices] = useState({});
    const [globalIndices, setGlobalIndices] = useState({});
    const [searchQuery, setSearchQuery] = useState('');
    const [searchResults, setSearchResults] = useState([]);
    const [showSearchResults, setShowSearchResults] = useState(false);
    const [recentlyViewed, setRecentlyViewed] = useState([]);
    const [popularStocks, setPopularStocks] = useState([]);
    const [searchLoading, setSearchLoading] = useState(false);
    const searchRef = useRef(null);

    const loadInitialData = useCallback(async () => {
        try {
            const indexData = await api.getIndices();
            if (indexData) setIndianIndices(indexData);
        } catch (e) {
            console.error("Indian indices load error:", e);
        }

        try {
            const gData = await api.getGlobalIndices();
            if (gData) setGlobalIndices(gData);
        } catch (e) {
            console.error("Global indices load error:", e);
        }

        try {
            const priceMap = await api.getPrices(DEFAULT_POPULAR);
            const stocksWithData = DEFAULT_POPULAR.map(sym => ({
                symbol: sym,
                price: priceMap[sym] || null
            }));
            setPopularStocks(stocksWithData);
        } catch (e) {
            console.error("Popular stocks load error:", e);
        }
    }, []);

    useEffect(() => {
        loadInitialData();

        const saved = localStorage.getItem('recentlyViewed');
        if (saved) {
            try { setRecentlyViewed(JSON.parse(saved)); } catch (e) {}
        }

        const interval = setInterval(() => {
            loadInitialData();
        }, 15000);

        const handleClickOutside = (event) => {
            if (searchRef.current && !searchRef.current.contains(event.target)) {
                setShowSearchResults(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);

        return () => {
            clearInterval(interval);
            document.removeEventListener('mousedown', handleClickOutside);
        };
    }, [loadInitialData]);

    const handleSearch = async (query) => {
        setSearchQuery(query);
        if (query.trim().length < 1) {
            setSearchResults([]);
            setShowSearchResults(false);
            return;
        }

        setSearchLoading(true);
        setShowSearchResults(true);
        try {
            const data = await api.searchStocks(query);
            setSearchResults(data || []);
        } catch (error) {
            console.error('Error searching:', error);
            setSearchResults([]);
        }
        setSearchLoading(false);
    };

    const addToRecentlyViewed = (symbol) => {
        const updated = [symbol, ...recentlyViewed.filter(s => s !== symbol)].slice(0, 8);
        setRecentlyViewed(updated);
        localStorage.setItem('recentlyViewed', JSON.stringify(updated));
    };

    const handleStockClick = (symbol) => {
        addToRecentlyViewed(symbol);
        setShowSearchResults(false);
        setSearchQuery('');
        onSelectStock(symbol);
    };

    const currentDisplayIndices = marketTab === 'global' ? globalIndices : indianIndices;

    return (
        <div className="fade-in" style={{ display: 'flex', flexDirection: 'column', gap: '24px' }}>
            {/* Groww Style Market Overview Tabs Bar */}
            <div>
                <div style={{
                    display: 'flex',
                    justifyContent: 'space-between',
                    alignItems: 'center',
                    marginBottom: '14px',
                    flexWrap: 'wrap',
                    gap: '10px'
                }}>
                    <h3 style={{ 
                        color: 'var(--text-secondary)', 
                        fontSize: '13px', 
                        fontWeight: '700',
                        textTransform: 'uppercase',
                        letterSpacing: '0.05em',
                        margin: 0
                    }}>
                        ⚡ Market Overview & World Indices
                    </h3>

                    {/* Segment Toggle Pills */}
                    <div style={{
                        display: 'flex',
                        gap: '6px',
                        background: '#111927',
                        padding: '4px',
                        borderRadius: '12px',
                        border: '1px solid var(--border-color)'
                    }}>
                        <button
                            onClick={() => setMarketTab('indian')}
                            style={{
                                padding: '6px 14px',
                                background: marketTab === 'indian' ? 'var(--accent-primary)' : 'transparent',
                                color: marketTab === 'indian' ? '#ffffff' : 'var(--text-secondary)',
                                border: 'none',
                                borderRadius: '8px',
                                cursor: 'pointer',
                                fontSize: '13px',
                                fontWeight: '700',
                                transition: 'all 0.2s'
                            }}
                        >
                            🇮🇳 Indian Markets
                        </button>
                        <button
                            onClick={() => setMarketTab('global')}
                            style={{
                                padding: '6px 14px',
                                background: marketTab === 'global' ? 'var(--accent-primary)' : 'transparent',
                                color: marketTab === 'global' ? '#ffffff' : 'var(--text-secondary)',
                                border: 'none',
                                borderRadius: '8px',
                                cursor: 'pointer',
                                fontSize: '13px',
                                fontWeight: '700',
                                transition: 'all 0.2s'
                            }}
                        >
                            🌐 Global Markets
                        </button>
                    </div>
                </div>

                {/* Market Indices Cards Grid */}
                <div style={{
                    display: 'grid',
                    gridTemplateColumns: 'repeat(auto-fit, minmax(210px, 1fr))',
                    gap: '14px'
                }}>
                    {Object.keys(currentDisplayIndices).length > 0 ? (
                        Object.entries(currentDisplayIndices).map(([name, data]) => {
                            const isPos = (data.change || 0) >= 0;
                            return (
                                <div key={name} className="soft-card" style={{
                                    padding: '16px 20px',
                                    display: 'flex',
                                    flexDirection: 'column',
                                    gap: '8px',
                                    background: 'linear-gradient(145deg, #182234 0%, #1c2a40 100%)'
                                }}>
                                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                                        <span style={{ fontSize: '13px', fontWeight: '700', color: 'var(--text-secondary)' }}>
                                            {name}
                                        </span>
                                        <span className={`soft-badge ${isPos ? 'positive' : 'negative'}`}>
                                            {isPos ? '▲' : '▼'} {data.change_percent ? Math.abs(data.change_percent).toFixed(2) : '0.00'}%
                                        </span>
                                    </div>
                                    <div style={{ fontSize: '22px', fontWeight: '800', color: 'var(--text-primary)' }}>
                                        {data.value ? data.value.toLocaleString('en-IN', { minimumFractionDigits: 2 }) : '---'}
                                    </div>
                                    <div style={{ 
                                        fontSize: '12px', 
                                        fontWeight: '600', 
                                        color: isPos ? 'var(--accent-emerald)' : 'var(--accent-rose)' 
                                    }}>
                                        {isPos ? '+' : ''}{data.change ? data.change.toFixed(2) : '0.00'} Today
                                    </div>
                                </div>
                            );
                        })
                    ) : (
                        <div style={{ color: 'var(--text-muted)', fontSize: '14px' }}>Loading market indices...</div>
                    )}
                </div>
            </div>

            {/* Live Search Bar */}
            <div ref={searchRef} style={{ position: 'relative' }}>
                <div style={{ position: 'relative' }}>
                    <input
                        type="text"
                        className="soft-input"
                        placeholder="🔍 Search Indian stocks (e.g. RELIANCE, TCS, HDFCBANK, INFY, SBIN)"
                        value={searchQuery}
                        onChange={(e) => handleSearch(e.target.value)}
                        onFocus={() => searchQuery.length >= 1 && setShowSearchResults(true)}
                        style={{
                            width: '100%',
                            padding: '16px 22px',
                            paddingRight: '50px',
                            borderRadius: 'var(--radius-md)',
                            fontSize: '15px',
                            background: '#111927',
                            border: '1px solid #2a3c57',
                            boxShadow: 'var(--shadow-soft)'
                        }}
                    />
                    {searchLoading && (
                        <span style={{
                            position: 'absolute',
                            right: '18px',
                            top: '50%',
                            transform: 'translateY(-50%)',
                            color: 'var(--accent-primary)',
                            fontSize: '14px'
                        }}>
                            ⏳
                        </span>
                    )}
                </div>

                {/* Search Results Dropdown */}
                {showSearchResults && searchResults.length > 0 && (
                    <div style={{
                        position: 'absolute',
                        top: '100%',
                        left: 0,
                        right: 0,
                        marginTop: '8px',
                        background: 'var(--bg-surface)',
                        border: '1px solid #2e4161',
                        borderRadius: 'var(--radius-md)',
                        maxHeight: '360px',
                        overflowY: 'auto',
                        zIndex: 1000,
                        boxShadow: '0 16px 40px rgba(0,0,0,0.6)'
                    }}>
                        {searchResults.map((stock) => (
                            <div
                                key={stock.symbol}
                                onClick={() => handleStockClick(stock.symbol)}
                                style={{
                                    padding: '14px 20px',
                                    cursor: 'pointer',
                                    borderBottom: '1px solid var(--border-color)',
                                    display: 'flex',
                                    justifyContent: 'space-between',
                                    alignItems: 'center',
                                    transition: 'background 0.2s ease'
                                }}
                                onMouseEnter={(e) => e.currentTarget.style.background = 'var(--bg-surface-hover)'}
                                onMouseLeave={(e) => e.currentTarget.style.background = 'transparent'}
                            >
                                <div>
                                    <div style={{ fontWeight: '700', fontSize: '15px', color: 'var(--text-primary)' }}>
                                        {stock.symbol}
                                    </div>
                                    <div style={{ fontSize: '12px', color: 'var(--text-secondary)' }}>
                                        {stock.name}
                                    </div>
                                </div>
                                <div style={{ textAlign: 'right' }}>
                                    {stock.price ? (
                                        <div style={{ fontWeight: '700', fontSize: '15px', color: 'var(--accent-emerald)' }}>
                                            ₹{stock.price.toLocaleString('en-IN', { minimumFractionDigits: 2 })}
                                        </div>
                                    ) : (
                                        <div style={{ color: 'var(--text-muted)', fontSize: '12px' }}>View details</div>
                                    )}
                                </div>
                            </div>
                        ))}
                    </div>
                )}
            </div>

            {/* Recently Viewed */}
            {recentlyViewed.length > 0 && (
                <div>
                    <h3 style={{ 
                        color: 'var(--text-secondary)', 
                        fontSize: '13px', 
                        fontWeight: '700',
                        textTransform: 'uppercase',
                        letterSpacing: '0.05em',
                        marginBottom: '10px' 
                    }}>
                        🕒 Recently Viewed
                    </h3>
                    <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap' }}>
                        {recentlyViewed.map((sym) => (
                            <button
                                key={sym}
                                onClick={() => handleStockClick(sym)}
                                className="soft-btn"
                                style={{
                                    background: '#111927',
                                    border: '1px solid var(--border-color)',
                                    color: 'var(--text-primary)',
                                    padding: '8px 16px',
                                    borderRadius: '20px',
                                    fontSize: '13px'
                                }}
                            >
                                {sym}
                            </button>
                        ))}
                    </div>
                </div>
            )}

            {/* Popular & Most Traded Equities */}
            <div>
                <h3 style={{ 
                    color: 'var(--text-secondary)', 
                    fontSize: '13px', 
                    fontWeight: '700',
                    textTransform: 'uppercase',
                    letterSpacing: '0.05em',
                    marginBottom: '14px' 
                }}>
                    🔥 Popular Indian Stocks
                </h3>
                <div style={{
                    display: 'grid',
                    gridTemplateColumns: 'repeat(auto-fill, minmax(210px, 1fr))',
                    gap: '14px'
                }}>
                    {popularStocks.map((stock) => (
                        <div
                            key={stock.symbol}
                            onClick={() => handleStockClick(stock.symbol)}
                            className="soft-card"
                            style={{
                                padding: '16px',
                                cursor: 'pointer',
                                display: 'flex',
                                justifyContent: 'space-between',
                                alignItems: 'center'
                            }}
                            onMouseEnter={(e) => {
                                e.currentTarget.style.transform = 'translateY(-2px)';
                                e.currentTarget.style.borderColor = 'var(--accent-primary)';
                            }}
                            onMouseLeave={(e) => {
                                e.currentTarget.style.transform = 'translateY(0)';
                                e.currentTarget.style.borderColor = 'var(--border-color)';
                            }}
                        >
                            <div>
                                <div style={{ color: 'var(--text-primary)', fontWeight: '700', fontSize: '15px' }}>
                                    {stock.symbol}
                                </div>
                                <div style={{ color: 'var(--accent-emerald)', fontWeight: '600', fontSize: '13px', marginTop: '4px' }}>
                                    {stock.price ? `₹${stock.price.toLocaleString('en-IN', { minimumFractionDigits: 2 })}` : 'Fetching...'}
                                </div>
                            </div>
                            <span style={{
                                width: '32px',
                                height: '32px',
                                borderRadius: '50%',
                                background: '#111927',
                                display: 'flex',
                                alignItems: 'center',
                                justifyContent: 'center',
                                color: 'var(--accent-primary)',
                                fontSize: '12px'
                            }}>
                                ➔
                            </span>
                        </div>
                    ))}
                </div>
            </div>
        </div>
    );
};

export default Explore;
